import React, { useEffect, useState } from "react";
import { useParams, useNavigate, useLocation } from "react-router-dom";
import Sidebar from "../components/Sidebar";
import { setUserData, getUserData, STORAGE_KEYS } from "../utils/storageManager";
import "../styles/Lesson.css";

// Helper function to format dates
function formatDate(date) {
  if (!date) return "just now";
  try {
    let d;
    // Handle string, Date object, or plain object with date properties
    if (typeof date === "string") {
      d = new Date(date);
    } else if (date instanceof Date) {
      d = date;
    } else if (typeof date === "object" && date.toString) {
      // Plain object - try to convert
      d = new Date(date.toString());
    } else {
      return "just now";
    }

    // Validate the date
    if (!(d instanceof Date) || isNaN(d)) {
      return "just now";
    }

    const now = new Date();
    const diffMs = now - d;
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMins / 60);
    const diffDays = Math.floor(diffHours / 24);

    if (diffMins < 1) return "just now";
    if (diffMins < 60) return `${diffMins}m ago`;
    if (diffHours < 24) return `${diffHours}h ago`;
    if (diffDays < 7) return `${diffDays}d ago`;
    return d.toLocaleDateString();
  } catch (error) {
    console.error("formatDate error:", error, date);
    return "just now";
  }
}

export default function Lesson() {
  const { lessonId } = useParams();
  const navigate = useNavigate();
  const location = useLocation();

  console.log("🔍 FULL location.state:", location.state);
  console.log("🔍 lessonId from params:", lessonId);

  let { lesson, lessons = [], subjectName = "General" } = location.state || {};
  console.log("🔍 lesson extracted from state:", lesson);
  console.log("🔍 lessons array:", lessons);
  console.log("🔍 subjectName extracted:", subjectName);
  console.log("🔍 lesson?.id:", lesson?.id);
  console.log("🔍 lesson?.title:", lesson?.title);

  // Ensure lesson always has the correct id from URL params
  if (lesson && !lesson.id) {
    lesson.id = lessonId;
    console.log(`✅ Assigned lesson ID from URL params: ${lessonId}`);
  }

  // Get current lesson index
  const currentLessonIndex = lessons.length > 0 ? lessons.findIndex(l => {
    const idMatch = String(l.id) === String(lessonId);
    console.log(`🔍 Comparing lesson IDs: "${l.id}" === "${lessonId}" (types: ${typeof l.id} vs ${typeof lessonId}) ? ${idMatch}`);
    return idMatch;
  }) : -1;
  console.log("🔍 currentLessonIndex:", currentLessonIndex);
  console.log("🔍 lessons.length:", lessons.length);

  const previousLesson = currentLessonIndex > 0 ? lessons[currentLessonIndex - 1] : null;
  const nextLesson = currentLessonIndex >= 0 && currentLessonIndex < lessons.length - 1 ? lessons[currentLessonIndex + 1] : null;
  console.log("🔍 previousLesson:", previousLesson);
  console.log("🔍 nextLesson:", nextLesson);

  // Navigation function for previous/next lessons
  function goToLesson(targetLesson) {
    if (targetLesson) {
      console.log("🔄 Navigating to lesson:", targetLesson);
      navigate(`/lesson/${targetLesson.id}`, { state: { lesson: targetLesson, lessons, subId: location.state?.subId } });
    }
  }

  // Fallback lesson data if state is not passed
  if (!lesson) {
    console.log("⚠️ No lesson in state, using fallback lesson with id:", lessonId);
    lesson = {
      id: lessonId,
      lesson_number: 1,
      title: "Introduction to Biology",
      description: "Master the concepts and skills in this lesson with guided lessons and tutor support.",
      videos: [
        { id: 1, title: "Introduction to Biology", url: "https://www.youtube.com/watch?v=tZE_fQFK8EY&list=PL8dPuuaLjXtPW_ofbxdHNciuLoTRLPMgB&index=2" },
        { id: 2, title: "Scientific Method", url: "https://www.youtube.com/watch?v=xOLcZMw0hd4&list=PL8dPuuaLjXtPW_ofbxdHNciuLoTRLPMgB&index=3" },
        { id: 3, title: "What do Biologists Do?", url: "https://www.youtube.com/watch?v=rgZhDoPgzK8&list=PL8dPuuaLjXtPW_ofbxdHNciuLoTRLPMgB&index=4" },
        { id: 4, title: "Organized Life", url: "https://www.youtube.com/watch?v=cjR5zPrVjTc&list=PL8dPuuaLjXtPW_ofbxdHNciuLoTRLPMgB&index=5" },
        { id: 5, title: "Introduction to Ecology", url: "https://www.youtube.com/watch?v=aO3Yp45zmw8&list=PL8dPuuaLjXtPW_ofbxdHNciuLoTRLPMgB&index=6" },
      ]
    };
  }

  console.log("✅ Final lesson object:", JSON.stringify(lesson, null, 2));

  const [tutors, setTutors] = useState([]);
  const [sessions, setSessions] = useState([]);
  const [selectedTutor, setSelectedTutor] = useState(null);
  const [signupProcessing, setSignupProcessing] = useState(false);
  const [bookingStatus, setBookingStatus] = useState(null);
  const [bookedSession, setBookedSession] = useState(null);
  const [watchedVideos, setWatchedVideos] = useState({});
  const [currentVideoPlayer, setCurrentVideoPlayer] = useState(null);
  const [activeStep, setActiveStep] = useState(1);
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState(null);
  const [worksheet1Answers, setWorksheet1Answers] = useState({});
  const [worksheet2Answers, setWorksheet2Answers] = useState({});
  const [worksheet1Submitted, setWorksheet1Submitted] = useState(false);
  const [worksheet2Submitted, setWorksheet2Submitted] = useState(false);
  const [step3Completed, setStep3Completed] = useState(false);
  const [step4Completed, setStep4Completed] = useState(false);
  const [step5Completed, setStep5Completed] = useState(false);
  const [step6Completed, setStep6Completed] = useState(false);
  const [lessonXPAwarded, setLessonXPAwarded] = useState(false);
  const [newQuestion, setNewQuestion] = useState("");
  const [newAnswer, setNewAnswer] = useState("");
  const [isTransitioning, setIsTransitioning] = useState(false);

  // Load Q&A questions from localStorage (shared with QnA.js page)
  const QNA_STORAGE_KEY = "scihub_qna_questions";
  const LESSON_PROGRESS_KEY = `lesson_progress_${lessonId}`;
  const [communityPosts, setCommunityPosts] = useState([]);

  // Get user from localStorage for user-specific storage
  const user = JSON.parse(localStorage.getItem("user") || "null") || null;
  const userId = user?.id;

  // Helper function to save lesson progress to localStorage (user-specific)
  const saveLessonProgress = (progressData) => {
    if (!userId) {
      console.warn("⚠️ No user ID available for saving lesson progress");
      return;
    }
    try {
      const currentProgress = getUserData(userId, STORAGE_KEYS.LESSON_PROGRESS, {});
      const updatedProgress = { ...currentProgress, ...progressData, lastSaved: new Date().toISOString() };
      setUserData(userId, STORAGE_KEYS.LESSON_PROGRESS, updatedProgress);
      console.log("💾 Lesson progress saved to user-specific storage:", updatedProgress);
    } catch (error) {
      console.error("❌ Error saving lesson progress:", error);
    }
  };

  // Helper function to load lesson progress from localStorage (user-specific)
  const loadLessonProgress = () => {
    if (!userId) {
      console.warn("⚠️ No user ID available for loading lesson progress");
      return null;
    }
    try {
      const progress = getUserData(userId, STORAGE_KEYS.LESSON_PROGRESS);
      if (progress) {
        console.log("📂 Loaded lesson progress from user-specific storage:", progress);
