                <div style={{
                  background: "linear-gradient(135deg, rgba(99, 102, 241, 0.15), rgba(147, 51, 234, 0.1))",
                  border: "1px solid rgba(99, 102, 241, 0.3)",
                  borderRadius: "12px",
                  padding: "1rem",
                  color: "#a5b4fc",
                  fontWeight: 500
                }}>✓ Booked a tutoring session</div>
                <div style={{
                  background: "linear-gradient(135deg, rgba(16, 185, 129, 0.15), rgba(0, 240, 255, 0.1))",
                  border: "1px solid rgba(16, 185, 129, 0.3)",
                  borderRadius: "12px",
                  padding: "1rem",
                  color: "#6ee7b7",
                  fontWeight: 500
                }}>✓ Completed 2 worksheets</div>
                <div style={{
                  background: "linear-gradient(135deg, rgba(16, 185, 129, 0.15), rgba(0, 240, 255, 0.1))",
                  border: "1px solid rgba(16, 185, 129, 0.3)",
                  borderRadius: "12px",
                  padding: "1rem",
                  color: "#6ee7b7",
                  fontWeight: 500
                }}>✓ Participated in Q&A</div>
                <div style={{
                  background: "linear-gradient(135deg, rgba(251, 146, 60, 0.15), rgba(250, 204, 21, 0.1))",
                  border: "1px solid rgba(251, 146, 60, 0.3)",
                  borderRadius: "12px",
                  padding: "1rem",
                  color: "#fdba74",
                  fontWeight: 500
                }}>✓ Played interactive games</div>
                <div style={{
                  background: "linear-gradient(135deg, rgba(168, 85, 247, 0.15), rgba(236, 72, 153, 0.1))",
                  border: "1px solid rgba(168, 85, 247, 0.3)",
                  borderRadius: "12px",
                  padding: "1rem",
                  color: "#d8b4fe",
                  fontWeight: 500
                }}>📚 Lesson Completed</div>
              </div>

              <button 
                className="step-complete-btn"
                onClick={() => {
                  console.log("✅ Marking lesson fully complete");
                  setStep6Completed(true);

                  // Get lessons from state
                  const { lessons = [] } = location.state || {};
                  const user = JSON.parse(localStorage.getItem("user") || "null") || null;

                  console.log("💾 SAVING LESSON COMPLETION:");
                  console.log("  - userId:", userId);
                  console.log("  - subjectName:", subjectName);
                  console.log("  - lesson.id:", lesson?.id);
                  console.log(`  - storage key will be: lesson_${subjectName}_completed_${lesson?.id}`);

                  // Mark current lesson as completed (organized by subject)
                  if (lesson && lesson.id) {
                    setUserData(userId, `lesson_${subjectName}_completed_${lesson.id}`, { 
                      lessonId: lesson.id,
                      subjectName: subjectName,
                      completedAt: new Date().toISOString()
                    });
                    console.log(`💾 Marked lesson as completed in ${subjectName}:`, lesson.id);
                  }

                  // Find current lesson index and unlock next lesson
                  const currentLessonIndex = lessons.findIndex(l => String(l.id) === String(lesson?.id));
                  if (currentLessonIndex >= 0 && currentLessonIndex < lessons.length - 1) {
                    const nextLesson = lessons[currentLessonIndex + 1];
                    console.log("🔓 Unlocking next lesson:", nextLesson);

                    // Save next lesson unlock to user-specific localStorage (organized by subject)
                    setUserData(userId, `lesson_${subjectName}_unlocked_${nextLesson.id}`, { 
                      lessonId: nextLesson.id,
                      subjectName: subjectName,
                      unlockedAt: new Date().toISOString()
                    });
                    console.log("💾 Saved unlock status for lesson", nextLesson.id);

                    // Also send to backend if user is logged in
                    if (user && user.id) {
                      fetch(`http://localhost:8080/lesson_progress/unlock`, {
                        method: "POST",
                        headers: { "Content-Type": "application/json" },
                        body: JSON.stringify({
                          user_id: user.id,
                          lesson_id: nextLesson.id,
                          unlocked_at: new Date().toISOString()
                        }),
                      })
                        .then(res => console.log("✅ Next lesson unlocked on backend, status:", res.status))
                        .catch(err => console.warn("⚠️ Could not unlock on backend:", err));
                    }
                  }

                  // Save to backend if user is logged in
                  if (user && user.id && lesson && lesson.id) {
                    fetch(`http://localhost:8080/lesson_progress/complete`, {
                      method: "POST",
                      headers: { "Content-Type": "application/json" },
                      body: JSON.stringify({ 
                        user_id: user.id, 
                        lesson_id: lesson.id,
                        completed_at: new Date().toISOString()
                      }),
                    })
                      .then(res => {
                        console.log("✅ Lesson marked as complete on backend, status:", res.status);
                        // Navigate to next lesson or back after a short delay for feedback
                        setTimeout(() => {
                          const currentLessonIndex = lessons.findIndex(l => String(l.id) === String(lesson?.id));
                          if (currentLessonIndex >= 0 && currentLessonIndex < lessons.length - 1) {
                            const nextLesson = lessons[currentLessonIndex + 1];
                            console.log("📚 Navigating to next lesson:", nextLesson.id);
                            navigate(`/lesson/${nextLesson.id}`, { state: { lesson: nextLesson, lessons, subId: location.state?.subId, subjectName } });
                          } else {
                            console.log("✅ No more lessons, navigating back");
                            navigate(-1);
                          }
                        }, 1000);
                      })
                      .catch(err => {
                        console.warn("⚠️ Could not save to backend:", err);
                        // Still navigate to next lesson even if backend save fails
                        setTimeout(() => {
                          const currentLessonIndex = lessons.findIndex(l => String(l.id) === String(lesson?.id));
                          if (currentLessonIndex >= 0 && currentLessonIndex < lessons.length - 1) {
                            const nextLesson = lessons[currentLessonIndex + 1];
                            console.log("📚 Navigating to next lesson (after error):", nextLesson.id);
                            navigate(`/lesson/${nextLesson.id}`, { state: { lesson: nextLesson, lessons, subId: location.state?.subId, subjectName } });
                          } else {
                            console.log("✅ No more lessons, navigating back");
                            navigate(-1);
                          }
                        }, 1000);
                      });
                  } else {
                    // No user or lesson, just navigate back
                    console.log("⚠️ No user or lesson ID, navigating back");
                    setTimeout(() => {
                      const currentLessonIndex = lessons.findIndex(l => String(l.id) === String(lesson?.id));
                      if (currentLessonIndex >= 0 && currentLessonIndex < lessons.length - 1) {
                        const nextLesson = lessons[currentLessonIndex + 1];
                        console.log("📚 Navigating to next lesson (no user):", nextLesson.id);
                        navigate(`/lesson/${nextLesson.id}`, { state: { lesson: nextLesson, lessons, subId: location.state?.subId, subjectName } });
                      } else {
                        console.log("✅ No more lessons, navigating back");
                        navigate(-1);
                      }
                    }, 1000);
                  }
                }}
                style={{
                  width: "100%",
                  background: "linear-gradient(135deg, #10b981, #059669)",
                  color: "white",
                  border: "none",
                  padding: "1rem 1.5rem",
                  borderRadius: "12px",
                  fontSize: "1rem",
                  fontWeight: "700",
                  cursor: "pointer",
                  transition: "all 0.3s ease",
                  boxShadow: "0 10px 25px rgba(16, 185, 129, 0.3)"
                }}
                onMouseEnter={(e) => {
                  e.target.style.transform = "translateY(-2px)";
                  e.target.style.boxShadow = "0 15px 35px rgba(16, 185, 129, 0.4)";
                }}
                onMouseLeave={(e) => {
                  e.target.style.transform = "translateY(0)";
                  e.target.style.boxShadow = "0 10px 25px rgba(16, 185, 129, 0.3)";
                }}
              >
                🎓 Finish & Return to Lessons
              </button>
            </div>

            {/* Review steps button */}
            <div style={{ 
              textAlign: "center",
              paddingTop: "2rem",
              borderTop: "1px solid rgba(148, 163, 184, 0.2)"
            }}>
              <p style={{ color: "#9ca3af", marginBottom: "1rem" }}>Want to review your work?</p>
              <button 
                onClick={() => {
                  console.log("📖 Reviewing all steps");
                  setActiveStep(1);
                }}
                style={{
                  padding: "0.75rem 1.5rem",
                  background: "rgba(148, 163, 184, 0.1)",
                  border: "1px solid rgba(148, 163, 184, 0.2)",
                  color: "#9ca3af",
                  borderRadius: "8px",
                  cursor: "pointer",
                  fontSize: "0.95rem",
                  fontWeight: "600",
                  transition: "all 0.2s ease"
                }}
                onMouseEnter={(e) => {
                  e.target.style.background = "rgba(148, 163, 184, 0.2)";
                  e.target.style.color = "#f9fafb";
                }}
                onMouseLeave={(e) => {
                  e.target.style.background = "rgba(148, 163, 184, 0.1)";
                  e.target.style.color = "#9ca3af";
                }}
              >
                📖 Review All Steps
              </button>
            </div>

            {/* Navigation buttons */}
            <div className="lesson-navigation-buttons" style={{ marginTop: "3rem", paddingTop: "2rem", borderTop: "1px solid rgba(148, 163, 184, 0.2)", display: "flex", gap: "1rem", justifyContent: "center", flexWrap: "wrap" }}>
              <button 
                className="nav-btn nav-btn-back"
                onClick={() => navigate(-1)}
                style={{
                  padding: "0.75rem 1.5rem",
                  background: "rgba(148, 163, 184, 0.1)",
                  border: "1px solid rgba(148, 163, 184, 0.2)",
                  color: "#9ca3af",
                  borderRadius: "8px",
                  cursor: "pointer",
                  fontSize: "0.95rem",
                  fontWeight: "600",
                  transition: "all 0.2s ease"
                }}
                onMouseEnter={(e) => {
                  e.target.style.background = "rgba(148, 163, 184, 0.2)";
                  e.target.style.color = "#f9fafb";
                }}
                onMouseLeave={(e) => {
                  e.target.style.background = "rgba(148, 163, 184, 0.1)";
                  e.target.style.color = "#9ca3af";
                }}
              >
                ↑ Back to Subject
              </button>
            </div>
          </section>
          )}
        </div>
      </main>
    </div>
  );
}
